head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf30200";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_datefmt_cal_strtDd
 * @description 초기화 — datefmt cal strt Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_strtDd = function () { $c.date.checkCalendarFormat("cal_strtDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_endDd
 * @description 초기화 — datefmt cal end Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_endDd = function () { $c.date.checkCalendarFormat("cal_endDd", "yyyyMMdd"); };

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_searchStripStateListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent('slc_stripYn').setValue($c.util.getComponent('slc_stripYn').getValue());
        $c.util.getComponent('slc_exrTp').setValue($c.util.getComponent('slc_exrTp').getValue());
        $c.util.getComponent('dma_hiddenStore').set('isu_nm', $c.util.getComponent('ipt_isuNm').getValue());
        $c.util.getComponent('slc_srchDdDiv').setValue($c.util.getComponent('slc_srchDdDiv').getValue());
        $c.util.getComponent('cal_strtDd').setValue($c.util.getComponent('cal_strtDd').getValue());
        $c.util.getComponent('cal_endDd').setValue($c.util.getComponent('cal_endDd').getValue());
        $('#paging7 table:first-child').attr('align', 'center');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30200.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(strip#searchstripstatelist vs strip#searchstripstatespec) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_strtDd();
        scwin.init_datefmt_cal_endDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf30200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_searchStripStateList_onclick
 * @description btn_searchStripStateList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchStripStateList_onclick = async function(e){
    try {
        await scwin.searchStripStateList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30200.btn_searchStripStateList_onclick' }); }
};

/**
 * @method
 * @name ipt_isuNm_onkeydown
 * @description ipt_isuNm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_isuNm_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        if(event.keyCode===13){$c.str.replaceAll(selfVar);await scwin.searchStripStateList();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf30200.ipt_isuNm_onkeydown' }); }
};

/**
 * @method
 * @name ipt_isuNm_onblur
 * @description ipt_isuNm 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuNm_onblur = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30200.ipt_isuNm_onblur' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["stripYn"] === 'Y') { await scwin.searchStripStateSpec(r["stdCd"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchStripStateList
 * @description search Strip State List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchStripStateList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchStripStateList",
        method: "post",
        action: action ?? "/strip/strip.do?method=searchStripStateList",
        ref: "dma_searchStripStateListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_searchStripStateSpec
 * @description search Strip State Spec 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchStripStateSpec = async function (action) {
    const sbmOptions = {
        id: "tx_fn_searchStripStateSpec",
        method: "post",
        action: action ?? "/strip/strip.do?method=searchStripStateSpec",
        ref: "dma_searchStripStateSpecReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_result_fmt_isuNm
 * @description grd result fmt isu Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_fmt_isuNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_result");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "stripYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "isuNm") : '') ?? '') + '</a>'; }
        return String((dl && dl.getCellData ? dl.getCellData(r, "isuNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_result.isuNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchStripStateList
 * @description search Strip State List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchStripStateList = async function () {
    await scwin.tx_fn_searchStripStateList('/strip/strip.do?method=searchStripStateList');
};

/**
 * @method
 * @name searchStripStateSpec
 * @description search Strip State Spec 처리
 * @param {String} stdCd stdCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchStripStateSpec = async function (stdCd) {
    $c.util.getComponent("dma_searchStripStateListReq").set("stdCd", stdCd);
    await scwin.tx_fn_searchStripStateSpec('/strip/strip.do?method=searchStripStateSpec');
};

/**
 * @method
 * @name krxpage_pagenavigator_103_onclick
 * @description krxpage_pagenavigator_103 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_103_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_searchStripStateListReq').set('pageIndex', pi);
        await scwin.searchStripStateList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf30200.krxpage_pagenavigator_103_onclick" });
    }
};
